        "answer": "साइन ऊर्ध्वाधर या लंबवत घटक की ढलान वाली लंबाई से तुलना करता है: दीवार की ऊंचाई के विरुद्ध सीढ़ी, ऊर्ध्वाधर उठान के विरुद्ध छत की कड़ी, उठान के विरुद्ध रैंप, या ऊंचाई अंतर के विरुद्ध सर्वेक्षण रेखा। यह अनुपात बताता है कि ढलान वाली दूरी का कितना हिस्सा ऊर्ध्वाधर है, जो ऊंचाइयों, खाली जगहों, और घटक गणनाओं के लिए उपयोगी है।"
