            "text": "El seno es una razón matemática, no una cantidad física con unidades. Su valor práctico proviene de comparar una componente vertical o perpendicular con una distancia inclinada, de calcular componentes cuando se conoce el ángulo y de verificar relaciones geométricas. No trates el seno por sí solo como un certificado de seguridad estructural, capacidad de carga, accesibilidad o cumplimiento de ingeniería."
