      "sec-intro": {
        "h2": "Что такое калькулятор синуса?",
        "blocks": [
          {
            "kind": "p",
            "text": "Калькулятор синуса отвечает на один вопрос: для острого угла прямоугольного треугольника, как сторона напротив угла соотносится с самой длинной стороной? Введите противолежащий катет и гипотенузу, и инструмент разделит противолежащий катет на гипотенузу, вернув [[\\sin(A)=a/c]]. У прямоугольного треугольника противолежащий катет равен 3 см, а гипотенуза 5 см, поэтому [[\\sin(A)=3/5=0.6]]. Это 0.6 и есть синус: он говорит, что противолежащий катет составляет 60 процентов гипотенузы. Это не угол, поэтому никогда не читайте его как [[0.6^\\circ]]. Прилежащий катет в это вычисление никогда не входит; противолежащего катета и гипотенузы самих по себе достаточно. Синус это одно из основных тригонометрических отношений, и его сила в том, что он сравнивает две длины так, что результат зависит только от угла, а не от размера треугольника. Если нужен угол в градусах, обратный синус превращает отношение в градусы."
          }
        ]
      },
