              ["[[45^\\circ]]", "Примерно 0.7071", "Противолежащий катет это примерно 70.71% гипотенузы"],
              ["[[60^\\circ]]", "Примерно 0.8660", "Противолежащий катет это примерно 86.60% гипотенузы"],
              ["[[80^\\circ]]", "Примерно 0.9848", "Противолежащий катет это примерно 98.48% гипотенузы"]
