            "kind": "p",
            "text": "Синус это первое из трёх основных отношений: разделите противолежащий катет на гипотенузу, и вы опишете, какая часть самой длинной стороны лежит напротив угла. Формуле [[\\sin(A)=a/c]] нужны только два измерения, ответ всегда безразмерное число между 0 и 1, и оно растёт с ростом опорного угла. Когда нужна неизвестная сторона, [[a=c\\sin(A)]] восстанавливает противолежащий катет; когда нужен угол, [[A=\\sin^{-1}(a/c)]] восстанавливает его. Лестница, стропило, пандус или учебный 3-4-5, метод никогда не меняется: определите противолежащий катет, определите гипотенузу, разделите и проверьте диапазоном от 0 до 1."
