            "text": "<strong>Étape 5 :</strong> Vérifiez le triangle. [[3^2+4^2=5^2]], et [[9+16=25]]. La vérification pythagoricienne confirme que ces longueurs de côtés forment un triangle rectangle, donc le résultat du sinus est fiable."
