        "question": "Quelle est la formule du sinus pour un triangle rectangle ?",
        "answer": "sin(A) = a / c : divisez le côté opposé a par l'hypoténuse c. Avec un côté opposé de 3 cm et une hypoténuse de 5 cm, le résultat est 3/5 = 0.6. Ce nombre décimal est la réponse complète, un rapport sans dimension, pas un angle."
