            "text": "Dies ist ein nützliches Sonderwinkel-Ergebnis: Bei 30 Grad ist die Gegenkathete genau halb so lang wie die Hypotenuse, weshalb dieses Dreieck in so vielen Lehrbuchaufgaben vorkommt."
