            "text": "Gleiche Katheten erzeugen gleiche Sinus- und Kosinuswerte für die beiden spitzen Winkel: Bei 45 Grad steht jeder spitze Winkel einer Kathete von 1 und einer Hypotenuse von [[\\sqrt{2}]] gegenüber, Sinus und Kosinus fallen also zusammen."
