    "faqs": [
      {
        "question": "Wie lautet die Sinus-Formel für ein rechtwinkliges Dreieck?",
        "answer": "sin(A) = a / c: Teilen Sie die Gegenkathete a durch die Hypotenuse c. Bei einer Gegenkathete von 3 cm und einer Hypotenuse von 5 cm ist das Ergebnis 3/5 = 0.6. Diese Dezimalzahl ist die vollständige Antwort, ein dimensionsloses Verhältnis, kein Winkel."
      },
      {
        "question": "Wie berechnet man den Sinus aus zwei Seitenlängen?",
        "answer": "Identifizieren Sie den Referenzwinkel A, messen Sie die Gegenkathete a und die Hypotenuse c in derselben Einheit, bestätigen Sie, dass beide positiv sind und c länger als a ist, und teilen Sie dann: sin(A) = a / c. Geben Sie auf dieser Seite die Gegenkathete in das erste Feld und die Hypotenuse in das zweite ein und klicken Sie dann auf Berechnen sin(A)."
      },
      {
        "question": "Was ist der Unterschied zwischen Sinus und Kosinus?",
        "answer": "Der Sinus teilt die Gegenkathete durch die Hypotenuse (a/c); der Kosinus teilt die Ankathete durch die Hypotenuse (b/c). Beide verwenden dieselbe Hypotenuse, aber der Zähler unterscheidet sich. Ein Ergebnis über 1 bedeutet, dass der Bruch umgedreht wurde oder eine Kathete falsch bezeichnet war."
      },
      {
        "question": "Warum ist der Sinus für einen spitzen Winkel in einem rechtwinkligen Dreieck kleiner als 1?",
        "answer": "In einem gültigen, nicht entarteten rechtwinkligen Dreieck ist die Hypotenuse strikt länger als jede der beiden Katheten, also 0 < a < c. Das Teilen einer kleineren Länge durch eine größere ergibt immer ein Ergebnis unter 1: 0 < a/c < 1 für jeden spitzen Referenzwinkel."
      },
      {
        "question": "Kann der Sinus für einen spitzen Winkel in einem gültigen rechtwinkligen Dreieck gleich 1 sein?",
        "answer": "Nein. Ein Sinus von genau 1 würde erfordern, dass die Gegenkathete der Hypotenuse entspricht, was das Dreieck zu einer vertikalen Linie ohne Breite kollabieren ließe. Der Wert 1 ist ein Grenzwert, der angenähert wird, wenn Winkel A sich 90 Grad nähert, niemals ein Wert, den ein echtes Dreieck erzeugt."
      },
      {
        "question": "Was bedeutet ein Sinuswert von 0.6?",
        "answer": "Die Gegenkathete macht 60 Prozent der Hypotenuse aus. In einem 3-4-5-Dreieck ist die Seite gegenüber Winkel A 3 Einheiten lang, während die Hypotenuse 5 Einheiten lang ist, also sin(A) = 3/5 = 0.6. Es beschreibt die Form des Dreiecks und ist kein Winkel von 0.6 Grad."
      },
      {
        "question": "Hat das Sinus-Verhältnis Maßeinheiten?",
        "answer": "Nein. Beide Eingaben sind Längen in derselben Einheit, die Einheiten kürzen sich also: 3 m / 5 m = 0.6, genau wie 300 cm / 500 cm = 0.6. Geben Sie den Sinus als einfache Zahl an, niemals mit Grad, Metern oder Fuß."
      },
      {
        "question": "Wie kann ich einen Winkel aus einem Sinus-Verhältnis finden?",
        "answer": "Wenden Sie den Arcussinus auf das Verhältnis an: A = sin^-1(a/c). Für sin(A) = 0.6 gilt A = sin^-1(0.6), etwa 36.87 Grad. Stellen Sie zuerst Ihren wissenschaftlichen Taschenrechner auf den Gradmodus. Der Rechner auf dieser Seite gibt das Verhältnis zurück, nicht den Winkel."
      },
      {
        "question": "Wie kann ich die Gegenkathete mit dem Sinus finden?",
        "answer": "Stellen Sie die Formel um zu a = c * sin(A). Wenn die Hypotenuse 10 m beträgt und Winkel A 30 Grad ist, sin(30 deg) = 0.5, also a = 10 * 0.5 = 5 m. Dies ist eine manuelle Umstellung; der Rechner auf dieser Seite gibt das Verhältnis aus Seitenlängen zurück, nicht fehlende Seiten."
      },
      {
        "question": "Was ist der Unterschied zwischen Sinus und Kosekans?",
        "answer": "Der Sinus teilt die Gegenkathete durch die Hypotenuse (a/c); der Kosekans ist sein Kehrwert, Hypotenuse geteilt durch Gegenkathete (c/a). Wenn sin(A) = 0.6 gilt, dann csc(A) = 1/0.6, etwa 1.6667. Die beiden sind Kehrwerte, niemals austauschbare Formeln."
      },
      {
        "question": "Kann ich den Sinus berechnen, ohne die Ankathete zu kennen?",
        "answer": "Ja. Die primäre Sinus-Formel verwendet nur die Gegenkathete und die Hypotenuse, die Ankathete geht also nie in die Berechnung ein. Die Ankathete wird erst nützlich, wenn der Satz des Pythagoras zur Prüfung des Dreiecks verwendet wird oder wenn Kosinus, Tangens oder Sekans in die Arbeit eingehen."
      },
      {
        "question": "Wie wird der Sinus in praktischen Messungen verwendet?",
        "answer": "Der Sinus vergleicht eine vertikale oder senkrechte Komponente mit einer schrägen Länge: eine Leiter gegen ihre Wandhöhe, einen Dachsparren gegen seine vertikale Höhe, eine Rampe gegen ihre Höhe oder eine Vermessungslinie gegen ihren Höhenunterschied. Das Verhältnis sagt Ihnen, welcher Anteil der schrägen Entfernung vertikal ist, was für Höhen, Freiräume und Komponentenberechnungen nützlich ist."
      }
    ],
