      "sec-intro": "Che cos'è una calcolatrice del rapporto del seno?",
      "sec-triangle": "Il cateto opposto e l'ipotenusa",
      "sec-whatis": "Comprendere il rapporto del seno",
      "sec-formula": "Come funziona la formula del seno",
      "sec-howto": "Come usare la calcolatrice del rapporto del seno",
      "sec-examples": "Esempi passo passo del calcolo del seno",
      "sec-applications": "Esempi reali di uso del rapporto del seno",
      "sec-angle": "La relazione tra il seno e l'ampiezza dell'angolo",
      "sec-hypotenuse": "Come trovare il cateto opposto con il seno",
      "sec-recover": "Come trovare un angolo da un rapporto del seno",
      "sec-mistakes": "Errori comuni nel calcolo del seno",
      "sec-verify": "Come verificare se il tuo risultato del seno è valido",
      "sec-vs": "Seno contro coseno, tangente e cosecante",
      "sec-related": "Esplora le calcolatrici trigonometriche correlate",
