            "text": "Una coscia di scala semplificata è lunga 5 m e copre un'altezza verticale di 3 m. La coscia è l'ipotenusa, [[c=5\\,\\text{m}]], e l'altezza verticale è il cateto opposto, [[a=3\\,\\text{m}]]:"
