            "text": "Seno e cosecante sono la coppia reciproca: [[\\csc(A)=1/\\sin(A)]]. Se [[\\sin(A)=0.6]], allora [[\\csc(A)\\approx1.6667]]. Ricorri al seno quando il cateto opposto è noto rispetto all'ipotenusa, quando una componente verticale deve essere confrontata con una lunghezza inclinata, o quando SOH è la mnemotecnica corrispondente; ricorri al coseno per adiacente su ipotenusa, alla tangente quando i due cateti sono noti, e alla cosecante quando l'ipotenusa viene confrontata con il cateto opposto."
