      "sec-conclusion": {
        "h2": "Usa il rapporto del seno con sicurezza",
        "blocks": [
          {
            "kind": "p",
            "text": "Il seno è il primo dei tre rapporti principali: dividi il cateto opposto per l'ipotenusa e avrai descritto quale porzione del lato più lungo si trova di fronte all'angolo. La formula [[\\sin(A)=a/c]] ha bisogno solo di due misure, la risposta è sempre un numero adimensionale tra 0 e 1, e cresce man mano che cresce l'angolo di riferimento. Quando serve un lato mancante, [[a=c\\sin(A)]] recupera il cateto opposto; quando serve l'angolo, [[A=\\sin^{-1}(a/c)]] lo recupera. Scala, puntone, rampa o il 3-4-5 del libro di testo, il metodo non cambia mai: identifica il cateto opposto, identifica l'ipotenusa, dividi e verifica con l'intervallo da 0 a 1."
          }
        ]
      }
